{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parser.js'
import { Sheet, formatValue } from './eval.js'
import { parseAddress, formatAddress, compareKeys } from './address.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^[^ \t]*/.exec(line)
  const token = m[0]
  const rest = line.slice(token.length).replace(/^[ \t]+/, '')
  const addr = parseAddress(token)
  if (!addr) fail(`error: line ${n}: invalid cell address ${token}`)
  if (cells.has(addr.key)) fail(`error: line ${n}: cell ${formatAddress(addr.key)} is declared twice`)
  cells.set(addr.key, rest)
})

const keys = [...cells.keys()].sort(compareKeys)
const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const k of keys) out.push(`${formatAddress(k)}=${formatValue(sheet.get(k))}`)
} else {
  for (const k of keys) {
    const content = cells.get(k)
    let deps = []
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (ast) {
        const set = new Set()
        collect(ast, set)
        deps = [...set].sort(compareKeys)
      }
    }
    out.push(`${formatAddress(k)}:` + deps.map((d) => ' ' + formatAddress(d)).join(''))
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))

function collect(node, set) {
  switch (node.type) {
    case 'ref':
      if (node.addr) set.add(node.addr.key)
      break
    case 'range':
      if (node.from && node.to) {
        const c1 = Math.min(node.from.col, node.to.col)
        const c2 = Math.max(node.from.col, node.to.col)
        const r1 = Math.min(node.from.row, node.to.row)
        const r2 = Math.max(node.from.row, node.to.row)
        for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) set.add(c * 1000 + r)
      }
      break
    case 'bin':
      collect(node.l, set)
      collect(node.r, set)
      break
    case 'un':
      collect(node.e, set)
      break
    case 'call':
      node.args.forEach((a) => collect(a, set))
      break
  }
}
"}

